private static void handleRadiationFX(EntityLivingBase entity) {

		World world = entity.world;

		if(!world.isRemote) {

			if(ContaminationUtil.isRadImmune(entity)) return;

			int ix = (int)MathHelper.floor(entity.posX);
			int iy = (int)MathHelper.floor(entity.posY);
			int iz = (int)MathHelper.floor(entity.posZ);

			float rad = ChunkRadiationManager.proxy.getRadiation(world, ix, iy, iz);

			float neut = HbmLivingProps.getNeutronActivation(entity);

			if(neut > 0 && !RadiationConfig.disableNeutron) {
				ContaminationUtil.contaminate(entity, HazardType.RADIATION, ContaminationType.RAD_BYPASS, neut / 20F);
				HbmLivingProps.setNeutronActivation(entity,neut*0.998816f);//20 minute half life
			}
			if(neut<1e-5)
				HbmLivingProps.setNeutronActivation(entity,0);
			if(world.provider instanceof WorldProviderHell && RadiationConfig.hellRad > 0 && rad < RadiationConfig.hellRad)
				rad = (float) RadiationConfig.hellRad;

			if(world.provider instanceof WorldProviderCelestial || world.provider instanceof WorldProviderOrbit) {
				if(world.getSavedLightValue(EnumSkyBlock.Sky, ix, iy, iz) - world.skylightSubtracted >= 14) {
					Target target = CelestialBody.getTarget(world, ix, iz);
					CBT_Atmosphere atmosphere = !target.inOrbit ? CelestialBody.getTrait(world, CBT_Atmosphere.class) : null;

					float targetRad = target.body.getSunPower();

					if(atmosphere != null) {
						targetRad -= (float)atmosphere.getPressure() * 4;
					}

					targetRad *= RadiationConfig.celestialRadMultiplier;

					if(targetRad > rad) rad = targetRad;
				}
			}

			if(rad > 0) ContaminationUtil.contaminate(entity, HazardType.RADIATION, ContaminationType.CREATIVE, rad / 20F);

			if(entity instanceof EntityPlayer && ((EntityPlayer)entity).capabilities.isCreativeMode) return;

			Random rand = new Random(entity.getEntityId());

			int r600 = rand.nextInt(600);
			int r1200 = rand.nextInt(1200);

			if(HbmLivingProps.getRadiation(entity) > 600) {

				if((world.getTotalWorldTime() + r600) % 600 < 20 && canVomit(entity)) {
					NBTTagCompound nbt = new NBTTagCompound();
					nbt.setString("type", "vomit");
					nbt.setString("mode", "blood");
					nbt.setInteger("count", 25);
					nbt.setInteger("entity", entity.getEntityId());
					PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(nbt, 0, 0, 0),  new TargetPoint(entity.dimension, entity.posX, entity.posY, entity.posZ, 25));

					if((world.getTotalWorldTime() + r600) % 600 == 1) {
						com.hbm.sound.WorldSoundEffects.play(world, ix, iy, iz, "hbm:player.vomit", 1.0F, 1.0F);
						entity.addPotionEffect(new PotionEffect(Potion.hunger.id, 60, 19));
					}
				}

			} else if(HbmLivingProps.getRadiation(entity) > 200 && (world.getTotalWorldTime() + r1200) % 1200 < 20 && canVomit(entity)) {

				NBTTagCompound nbt = new NBTTagCompound();
				nbt.setString("type", "vomit");
				nbt.setString("mode", "normal");
				nbt.setInteger("count", 15);
				nbt.setInteger("entity", entity.getEntityId());
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(nbt, 0, 0, 0),  new TargetPoint(entity.dimension, entity.posX, entity.posY, entity.posZ, 25));

				if((world.getTotalWorldTime() + r1200) % 1200 == 1) {
					com.hbm.sound.WorldSoundEffects.play(world, ix, iy, iz, "hbm:player.vomit", 1.0F, 1.0F);
					entity.addPotionEffect(new PotionEffect(Potion.hunger.id, 60, 19));
				}

			}

			if(HbmLivingProps.getRadiation(entity) > 900 && (world.getTotalWorldTime() + rand.nextInt(10)) % 10 == 0) {

				NBTTagCompound nbt = new NBTTagCompound();
				nbt.setString("type", "sweat");
				nbt.setInteger("count", 1);
				nbt.setInteger("block", Block.getIdFromBlock(Blocks.REDSTONE_BLOCK));
				nbt.setInteger("entity", entity.getEntityId());
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(nbt, 0, 0, 0),  new TargetPoint(entity.dimension, entity.posX, entity.posY, entity.posZ, 25));

			}
		} else {
			float radiation = HbmLivingProps.getRadiation(entity);

			if(entity instanceof EntityPlayer && radiation > 600) {

				NBTTagCompound nbt = new NBTTagCompound();
				nbt.setString("type", "radiation");
				nbt.setInteger("count", radiation > 900 ? 4 : radiation > 800 ? 2 : 1);
				MainRegistry.proxy.effectNT(nbt);
			}
		}
	}

