@Override
	protected void onFoodEaten(ItemStack stack, World world, EntityPlayer player) {
		if(!world.isRemote) {

			VersatileConfig.applyPotionSickness(player, 5);

			if(this == ModItems.pill_iodine) {
				player.removePotionEffect(Potion.blindness.id);
				player.removePotionEffect(Potion.confusion.id);
				player.removePotionEffect(Potion.digSlowdown.id);
				player.removePotionEffect(Potion.hunger.id);
				player.removePotionEffect(Potion.moveSlowdown.id);
				player.removePotionEffect(Potion.poison.id);
				player.removePotionEffect(Potion.weakness.id);
				player.removePotionEffect(Potion.wither.id);
				player.removePotionEffect(HbmPotion.radiation.id);
			}

			if(this == ModItems.plan_c) {
				for(int i = 0; i < 10; i++)
					player.attackEntityFrom(rand.nextBoolean() ? ModDamageSource.euthanizedSelf : ModDamageSource.euthanizedSelf2, 1000);
			}

			if(this == ModItems.pill_red) {
				player.addPotionEffect(new PotionEffect(HbmPotion.death.id, 60 * 60 * 20, 0));
			}

			if(this == ModItems.radx) {
				player.addPotionEffect(new PotionEffect(HbmPotion.radx.id, 3 * 60 * 20, 0));
			}

			if(this == ModItems.siox) {
				HbmLivingProps.setAsbestos(player, 0);
				HbmLivingProps.setBlackLung(player, Math.min(HbmLivingProps.getBlackLung(player), HbmLivingProps.maxBlacklung / 5));
			}

			if(this == ModItems.pill_herbal) {
				HbmLivingProps.setAsbestos(player, 0);
				HbmLivingProps.setBlackLung(player, Math.min(HbmLivingProps.getBlackLung(player), HbmLivingProps.maxBlacklung / 5));
				HbmLivingProps.incrementRadiation(player, -100F);

				player.addPotionEffect(new PotionEffect(Potion.confusion.id, 10 * 20, 0));
				player.addPotionEffect(new PotionEffect(Potion.weakness.id, 10 * 60 * 20, 2));
				player.addPotionEffect(new PotionEffect(Potion.digSlowdown.id, 10 * 60 * 20, 2));
				player.addPotionEffect(new PotionEffect(Potion.poison.id, 5 * 20, 2));

				PotionEffect eff = new PotionEffect(HbmPotion.potionsickness.id, 10 * 60 * 20);
				eff.setCurativeItems(new ArrayList());
				player.addPotionEffect(eff);
			}

			if(this == ModItems.xanax) {
				float digamma = HbmLivingProps.getDigamma(player);
				HbmLivingProps.setDigamma(player, Math.max(digamma - 0.5F, 0F));
			}
			if(this == ModItems.animan) {
				int x = (int)MathHelper.floor(player.posX);
				int y = (int)MathHelper.floor(player.posY);
				int z = (int)MathHelper.floor(player.posZ);
				world.playSoundEffect(x, y, z, "hbm:player.oil", 1.0F, 1.0F);

				player.addPotionEffect(new PotionEffect(HbmPotion.run.id, 10 * 20, 0));

				NBTTagCompound nbt = new NBTTagCompound();
				nbt.setString("type", "vomit");
				nbt.setString("mode", "normal");
				nbt.setInteger("count", 25);
				nbt.setInteger("entity", player.getEntityId());
				PacketDispatcher.wrapper.sendToAllAround(new AuxParticlePacketNT(nbt, 0, 0, 0),  new TargetPoint(player.dimension, x, y, z, 25));

				com.hbm.sound.WorldSoundEffects.play(world, x, y, z, "hbm:player.vomit", 1.0F, 1.0F);
				player.addPotionEffect(new PotionEffect(Potion.hunger.id, 60, 19));

			}
			if(this == ModItems.chocolate) {
				if(rand.nextInt(25) == 0) {
					player.attackEntityFrom(ModDamageSource.overdose, 1000);
				}
				player.addPotionEffect(new PotionEffect(Potion.digSpeed.id, 60 * 20, 3));
				player.addPotionEffect(new PotionEffect(Potion.moveSpeed.id, 60 * 20, 3));
				player.addPotionEffect(new PotionEffect(Potion.jump.id, 60 * 20, 3));
			}

			if(this == ModItems.fmn) {
				float digamma = HbmLivingProps.getDigamma(player);
				HbmLivingProps.setDigamma(player, Math.min(digamma, 2F));
				player.addPotionEffect(new PotionEffect(Potion.blindness.id, 60, 0));
			}

			if(this == ModItems.five_htp) {
				HbmLivingProps.setDigamma(player, 0);
				player.addPotionEffect(new PotionEffect(HbmPotion.stability.id, 10 * 60 * 20, 0));
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			if(!this.isLoaded()) {
				started = false;
			}

			if(started) {
				timer--;

				if(timer % 20 == 0)
					com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.fstbmbPing", 5.0F, 1.0F);
			}

			if(timer <= 0) {
				explode();
			}

			networkPackNT(250);
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			if(started) {
				timer--;

				if(timer % 20 == 0 && timer > 0)
					com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.fstbmbPing", 1.0F, 1.0F);

				if(timer <= 0) {
					((BlockChargeBase)this.getBlockType()).explode(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ());
				}
			}

			networkPackNT(100);
		}
	}

public void launchTo(int tX, int tZ) {

		com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.missileTakeOff", 10.0F, 1.0F);

		ItemCustomMissilePart chip = (ItemCustomMissilePart) Item.getItemById(ItemCustomMissile.readFromNBT(slots[0], "chip"));
		float c = (Float)chip.attributes[0];
		float f = 1.0F;

		if(getStruct(slots[0]).fins != null) {
			ItemCustomMissilePart fins = (ItemCustomMissilePart) Item.getItemById(ItemCustomMissile.readFromNBT(slots[0], "stability"));
			f = (Float) fins.attributes[0];
		}

		Vec3d target = new Vec3d(this.pos.getX() - tX, 0, this.pos.getZ() - tZ);
		target = new Vec3d(target.x * c * f, target.y, target.z * c * f);

		target = target.rotateYaw(this.world.rand.nextFloat() * 360);

		EntityMissileCustom missile = new EntityMissileCustom(this.world, this.pos.getX() + 0.5F, this.pos.getY() + 2.5F, this.pos.getZ() + 0.5F, tX + (int)target.x, tZ + (int)target.z, getStruct(slots[0]));
		this.world.spawnEntityInWorld(missile);

		subtractFuel();

		slots[0] = null;
	}

public void finalizeLaunch(Entity missile) {
		this.world.spawnEntityInWorld(missile);
		TrackerUtil.setTrackingRange(this.world, missile, 500);
		com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX() + 0.5, this.pos.getY(), this.pos.getZ() + 0.5, "hbm:weapon.missileTakeOff", 2.0F, 1.0F);

		this.power -= 75_000;

		if(slots[0] != null && slots[0].getItem() instanceof ItemMissile) {
			ItemMissile item = (ItemMissile) slots[0].getItem();
			tanks[0].setFill(tanks[0].getFill() - item.fuelCap);
			tanks[1].setFill(tanks[1].getFill() - item.fuelCap);
		}

		this.decrStackSize(0, 1);
	}

public BombReturnCode launch() {

		if(slots[1] != null && slots[2] != null && slots[3] != null && this.missileLoaded) {
			if(slots[1].getItem() == ModItems.launch_code && slots[2].getItem() == ModItems.launch_key) {
				if(slots[3] != null && slots[3].getItem() instanceof IDesignatorItem) {
					IDesignatorItem designator = (IDesignatorItem) slots[3].getItem();

					if(!designator.isReady(this.world, slots[3], this.pos.getX(), this.pos.getY(), this.pos.getZ())) return BombReturnCode.ERROR_MISSING_COMPONENT;

					Vec3d coords = designator.getCoords(this.world, slots[3], this.pos.getX(), this.pos.getY(), this.pos.getZ());
					int targetX = (int) Math.floor(coords.x);
					int targetZ = (int) Math.floor(coords.z);

					EntityMissileDoomsdayRusted missile = new EntityMissileDoomsdayRusted(this.world, this.pos.getX() + 0.5F, this.pos.getY() + 1F, this.pos.getZ() + 0.5F, targetX, targetZ);
					this.world.spawnEntityInWorld(missile);
					TrackerUtil.setTrackingRange(this.world, missile, 500);
					com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX() + 0.5, this.pos.getY(), this.pos.getZ() + 0.5, "hbm:weapon.missileTakeOff", 2.0F, 1.0F);
					this.missileLoaded = false;
					this.decrStackSize(1, 1);
					this.markDirty();

					return BombReturnCode.LAUNCHED;
				}
			}
		}

		return BombReturnCode.ERROR_MISSING_COMPONENT;
	}

