@Override
	public void update() {

		if(!this.world.isRemote) {
			this.tryPullHeat();

			if(this.world.getTotalWorldTime() % 20 == 0) {
				for(int i = 2; i < 6; i++) {
					ForgeDirection dir = ForgeDirection.getOrientation(i);
					ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

					for(int y = this.pos.getY(); y <= this.pos.getY() + 1; y++) {
						for(int j = -1; j <= 1; j++) {
							if(tank.getFill() > 0) this.sendFluid(tank, this.world, this.pos.getX() + dir.offsetX * 2 + rot.offsetX * j, y, this.pos.getZ() + dir.offsetZ * 2 + rot.offsetZ * j, dir);
							this.sendSmoke(this.pos.getX() + dir.offsetX * 2 + rot.offsetX * j, y, this.pos.getZ() + dir.offsetZ * 2 + rot.offsetZ * j, dir);
						}
					}
				}

				for(int x = this.pos.getX() - 1; x <= this.pos.getX() + 1; x++) {
					for(int z = this.pos.getZ() - 1; z <= this.pos.getZ() + 1; z++) {
						if(tank.getFill() > 0) this.sendFluid(tank, this.world, x, this.pos.getY() + 2, z, ForgeDirection.UP);
						this.sendSmoke(x, this.pos.getY() + 2, z, ForgeDirection.UP);
					}
				}
			}

			this.wasOn = false;

			tank.unloadTank(2, 3, slots);

			if(canSmelt()) {
				int burn = heat / 100;

				if(burn > 0) {
					this.wasOn = true;
					this.progress += burn;
					this.heat -= burn;

					if(progress >= processTime) {
						this.markChanged();
						progress -= this.processTime;

						Pair<ItemStack, FluidStack> pair = CombinationRecipes.getOutput(slots[0]);
						ItemStack out = pair.getKey();
						FluidStack fluid = pair.getValue();

						if(out != null)  {
							if(slots[1] == null) {
								slots[1] = out.copy();
							} else {
								slots[1].stackSize += out.stackSize;
							}
						}

						if(fluid != null) {
							if(tank.getTankType() != fluid.type) {
								tank.setTankType(fluid.type);
							}

							tank.setFill(tank.getFill() + fluid.fill);
						}

						this.decrStackSize(0, 1);
					}

					List<Entity> entities = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - 0.5, this.pos.getY() + 2, this.pos.getZ() - 0.5, this.pos.getX() + 1.5, this.pos.getY() + 4, this.pos.getZ() + 1.5));

					for(Entity e : entities) e.setFire(5);

					if(this.world.getTotalWorldTime() % 10 == 0) com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY() + 1, this.pos.getZ(), "hbm:weapon.flamethrowerShoot", 0.25F, 0.5F);
					if(this.world.getTotalWorldTime() % 20 == 0) this.pollute(PollutionType.SOOT, PollutionHandler.SOOT_PER_SECOND * 3);
				}
			} else {
				this.progress = 0;
			}

			this.networkPackNT(50);
		} else {

			if(this.wasOn && this.world.rand.nextInt(15) == 0) {
				this.world.spawnParticle("lava", this.pos.getX() + 0.5 + this.world.rand.nextGaussian() * 0.5, this.pos.getY() + 2, this.pos.getZ() + 0.5 + this.world.rand.nextGaussian() * 0.5, 0, 0, 0);
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			this.fluidUsed = 0;
			this.output = 0;

			for(DirPos pos : getConPos()) {
				this.tryProvide(this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				this.trySubscribe(tank.getTankType(), this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
			}

			tank.setType(3, slots);
			tank.loadTank(1, 2, slots);

			int maxVent = 50;
			int maxBurn = 10;

			if(isOn && tank.getFill() > 0) {

				upgradeManager.checkSlots(this, slots, 4, 5);
				int burn = upgradeManager.getLevel(UpgradeType.SPEED);
				int yield = upgradeManager.getLevel(UpgradeType.EFFECT);

				maxVent += maxVent * burn;
				maxBurn += maxBurn * burn;

				if(!doesBurn || !tank.getTankType().hasTrait(FT_Flammable.class) || !breatheAir(Math.min(maxBurn, tank.getFill()))) {

					if(tank.getTankType().hasTrait(FT_Gaseous.class) || tank.getTankType().hasTrait(FT_Gaseous_ART.class)) {
						int eject = Math.min(maxVent, tank.getFill());
						this.fluidUsed = eject;
						tank.setFill(tank.getFill() - eject);
						tank.getTankType().onFluidRelease(this, tank, eject);

						if(this.world.getTotalWorldTime() % 7 == 0)
							this.world.playSoundEffect(this.pos.getX(), this.pos.getY() + 11, this.pos.getZ(), "random.fizz", getVolume(1.5F), 0.5F);

						if(this.world.getTotalWorldTime() % 5 == 0 && eject > 0) {
							FT_Polluting.pollute(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), tank.getTankType(), FluidReleaseType.SPILL, eject * 5);
						}

						CelestialBody.emitGas(this.world, tank.getTankType(), eject);
					}
				} else {

					if(tank.getTankType().hasTrait(FT_Flammable.class)) {
						int eject = Math.min(maxBurn, tank.getFill());
						this.fluidUsed = eject;
						tank.setFill(tank.getFill() - eject);

						int penalty = 5;
						if(!tank.getTankType().hasTrait(FT_Gaseous.class) && !tank.getTankType().hasTrait(FT_Gaseous_ART.class))
							penalty = 10;

						long powerProd = tank.getTankType().getTrait(FT_Flammable.class).getHeatEnergy() * eject / 1_000; // divided by 1000 per mB
						powerProd /= penalty;
						powerProd += powerProd * yield / 3;

						this.output = (int) powerProd;
						power += powerProd;

						if(power > maxPower)
							power = maxPower;

						ParticleUtil.spawnGasFlame(this.world, this.pos.getX() + 0.5F, this.pos.getY() + 11.75F, this.pos.getZ() + 0.5F, this.world.rand.nextGaussian() * 0.15, 0.2, this.world.rand.nextGaussian() * 0.15);

						List<Entity> list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - 1, this.pos.getY() + 12, this.pos.getZ() - 2, this.pos.getX() + 2, this.pos.getY() + 17, this.pos.getZ() + 2));
						for(Entity e : list) {
							e.setFire(5);
							e.attackEntityFrom(DamageSource.onFire, 5F);
						}

						if(this.world.getTotalWorldTime() % 3 == 0)
							com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY() + 11, this.pos.getZ(), "hbm:weapon.flamethrowerShoot", getVolume(1.5F), 0.75F);

						if(this.world.getTotalWorldTime() % 5 == 0 && eject > 0) {
							FT_Polluting.pollute(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), tank.getTankType(), FluidReleaseType.BURN, eject * 5);
						}
					}
				}
			}

			power = Library.chargeItemsFromTE(slots, 0, power, maxPower);

			this.networkPackNT(50);

		} else {

			if(isOn && tank.getFill() > 0) {

				if((!doesBurn || !(tank.getTankType().hasTrait(FT_Flammable.class))) && (tank.getTankType().hasTrait(FT_Gaseous.class) || tank.getTankType().hasTrait(FT_Gaseous_ART.class))) {

					NBTTagCompound data = new NBTTagCompound();
					data.setString("type", "tower");
					data.setFloat("lift", 1F);
					data.setFloat("base", 0.25F);
					data.setFloat("max", 3F);
					data.setInteger("life", 150 + this.world.rand.nextInt(20));
					data.setInteger("color", tank.getTankType().getColor());

					data.setDouble("posX", this.pos.getX() + 0.5);
					data.setDouble("posZ", this.pos.getZ() + 0.5);
					data.setDouble("posY", this.pos.getY() + 11);

					MainRegistry.proxy.effectNT(data);

				}

				if(doesBurn && tank.getTankType().hasTrait(FT_Flammable.class) && MainRegistry.proxy.me().getDistanceSq(this.pos.getX(), this.pos.getY() + 10, this.pos.getZ()) <= 1024) {

					NBTTagCompound data = new NBTTagCompound();
					data.setString("type", "vanillaExt");
					data.setString("mode", "smoke");
					data.setBoolean("noclip", true);
					data.setInteger("overrideAge", 50);

					if(this.world.getTotalWorldTime() % 2 == 0) {
						data.setDouble("posX", this.pos.getX() + 1.5);
						data.setDouble("posZ", this.pos.getZ() + 1.5);
						data.setDouble("posY", this.pos.getY() + 10.75);
					} else {
						data.setDouble("posX", this.pos.getX() + 1.125);
						data.setDouble("posZ", this.pos.getZ() - 0.5);
						data.setDouble("posY", this.pos.getY() + 11.75);
					}

					MainRegistry.proxy.effectNT(data);
				}
			}
		}
	}

@Override
	public void updateFiringTick() {

		timer++;

		int delay = mode == MODE_ARTILLERY ? 300 : 40;

		if(timer % delay == 0) {

			ItemStack conf = this.getShellLoaded();

			if(conf != null) {
				cachedCasingConfig = ItemAmmoArty.itemTypes[conf.getItemDamage()].casing;
				this.spawnShell(conf);
				this.conusmeAmmo(ModItems.ammo_arty);
				com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.jeremy_fire", 25.0F, 1.0F);
				Vec3d pos = this.getTurretPos();
				com.hbm.util.Vec3NT vec = new com.hbm.util.Vec3NT(this.getBarrelLength(), 0, 0);
				vec.rotateAroundZRad((float) -this.rotationPitch);
				vec.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));
				this.didJustShoot = true;

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "vanillaExt");
				data.setString("mode", "largeexplode");
				data.setFloat("size", 0F);
				data.setByte("count", (byte)5);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, pos.x + vec.x, pos.y + vec.y, pos.z + vec.z), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 150));
			}

			if(this.mode == this.MODE_MANUAL && !this.targetQueue.isEmpty()) {
				this.targetQueue.remove(0);
				this.tPos = null;
			}
		}
	}

@Override
	public void updateFiringTick() {

		if(this.tank.getTankType().hasTrait(FT_Flammable.class) && this.tank.getTankType().hasTrait(FT_Liquid.class) && this.tank.getFill() >= 2) {

			FT_Flammable trait = this.tank.getTankType().getTrait(FT_Flammable.class);
			this.tank.setFill(this.tank.getFill() - 2);

			Vec3d pos = this.getTurretPos();
			com.hbm.util.Vec3NT vec = new com.hbm.util.Vec3NT(this.getBarrelLength(), 0, 0);
			vec.rotateAroundZRad((float) -this.rotationPitch);
			vec.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));

			float damage = Math.min((float) (trait.getHeatEnergy() / 500_000F), 20F);
			EntityBulletBaseMK4 proj = new EntityBulletBaseMK4(this.world, tank.getTankType() == Fluids.BALEFIRE ? XFactoryFlamer.flame_nograv_bf : XFactoryFlamer.flame_nograv, damage, 0.05F, (float) rotationYaw, (float) rotationPitch);
			proj.setPositionAndRotation(pos.x + vec.x, pos.y + vec.y, pos.z + vec.z, proj.rotationYaw, proj.rotationPitch);
			this.world.spawnEntityInWorld(proj);

			com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.flamethrowerShoot", 2F, 1F + this.world.rand.nextFloat() * 0.5F);
		}
	}

@Override
	public void update() {

		if(reload > 0)
			reload--;

		if(reload == 1)
			com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.jeremy_reload", 2.0F, 1.0F);

		super.update();
	}

@Override
	public void updateFiringTick() {

		timer++;

		if(timer % 40 == 0) {

			BulletConfig conf = this.getFirstConfigLoaded();

			if(conf != null) {
				this.cachedCasingConfig = conf.casing;
				this.spawnBullet(conf, 50F);
				this.conusmeAmmo(conf.ammo);
				com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.jeremy_fire", 4.0F, 1.0F);
				Vec3d pos = this.getTurretPos();
				com.hbm.util.Vec3NT vec = new com.hbm.util.Vec3NT(this.getBarrelLength(), 0, 0);
				vec.rotateAroundZRad((float) -this.rotationPitch);
				vec.rotateAroundYRad((float) -(this.rotationYaw + Math.PI * 0.5));

				reload = 20;

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "vanillaExt");
				data.setString("mode", "largeexplode");
				data.setFloat("size", 0F);
				data.setByte("count", (byte)5);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, pos.x + vec.x, pos.y + vec.y, pos.z + vec.z), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 50));
